//! Conducting sheets on cylindrical grids against the black-box openEMS
//! (design §5.16.2; fixtures `tests/fixtures/openems/cyl_sheet_*`,
//! regenerated by `scripts/openems-oracle/gen-cyl.sh`): a closed half-wave
//! coaxial cavity (`a = 2 mm`, `b = 6 mm`, `L = 30 mm`) whose TEM mode
//! (≈ 5 GHz) rings down with a lossy inner tube (`ρ = const` sheet) or a
//! resistive fin (`α = const` sheet, at `α = π/2` and on the `α = 0` seam).
//!
//! openEMS's sheet model is not ems's slab model (§5.9), on cylindrical
//! grids as on Cartesian ones; the tests record how they differ: openEMS's
//! tube has half the loss (twice the `Q`), its thin resistive fin is
//! nearly reactive (the mode detunes by −13 %), and its fin on the seam has
//! no effect. ems's values are the analytic ones (`tests/cylindrical_sheet.rs`).
//! Also: openEMS ignores plane waves on cylindrical grids (`cyl_planewave`).
#![cfg(feature = "xml")]

use std::f64::consts::TAU;
use std::path::{Path, PathBuf};

use ems::Simulation;

fn fixture(case: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/openems")
        .join(case)
}

/// `(t, v)` of an openEMS probe file.
fn read_probe(path: &Path) -> (Vec<f64>, Vec<f64>) {
    let text = std::fs::read_to_string(path).unwrap();
    text.lines()
        .filter(|l| !l.starts_with('%') && !l.trim().is_empty())
        .map(|l| {
            let mut it = l.split_whitespace().map(|x| x.parse::<f64>().unwrap());
            (it.next().unwrap(), it.next().unwrap())
        })
        .unzip()
}

/// `(f, Q)` of the ring-down after 2 ns: spectral peak in 4–6 GHz, then a
/// least-squares fit of the log of the energy per period.
fn q_of(t: &[f64], v: &[f64]) -> (f64, f64) {
    let dt = t[1] - t[0];
    let t0 = t.iter().position(|&x| x >= 2e-9).unwrap();
    let tail = &v[t0..];
    let spec = |f: f64| {
        let (mut re, mut im) = (0.0, 0.0);
        for (n, &x) in tail.iter().enumerate() {
            let (s, c) = (TAU * f * n as f64 * dt).sin_cos();
            re += x * c;
            im -= x * s;
        }
        re.hypot(im)
    };
    let (mut lo, mut hi) = (4e9, 6e9);
    for _ in 0..60 {
        let (a, b) = (lo + (hi - lo) / 3.0, hi - (hi - lo) / 3.0);
        if spec(a) < spec(b) {
            lo = a;
        } else {
            hi = b;
        }
    }
    let f = 0.5 * (lo + hi);
    let per = 1.0 / (f * dt);
    let n = (tail.len() as f64 / per).floor() as usize;
    let pts: Vec<(f64, f64)> = (0..n)
        .map(|p| {
            let (a, b) = ((p as f64 * per) as usize, ((p + 1) as f64 * per) as usize);
            let e: f64 = tail[a..b].iter().map(|x| x * x).sum::<f64>() / (b - a) as f64;
            ((p as f64 + 0.5) * per * dt, e.ln())
        })
        .collect();
    let m = pts.len() as f64;
    let (mx, my) = pts
        .iter()
        .fold((0.0, 0.0), |a, p| (a.0 + p.0 / m, a.1 + p.1 / m));
    let slope = pts.iter().map(|p| (p.0 - mx) * (p.1 - my)).sum::<f64>()
        / pts.iter().map(|p| (p.0 - mx).powi(2)).sum::<f64>();
    (f, -TAU * f / slope)
}

/// `(f, Q)` of openEMS and of ems for `case`.
fn both(case: &str) -> ((f64, f64), (f64, f64)) {
    let (t, v) = read_probe(&fixture(case).join("v0"));
    let oe = q_of(&t, &v);
    let mut sim = Simulation::from_xml(fixture(case).join("model.xml")).unwrap();
    let res = sim.run().unwrap();
    let p = res.probe("v0").unwrap();
    let em = q_of(p.times(), p.scalar().unwrap());
    eprintln!(
        "{case}: openEMS f {:.4} GHz Q {:.2}; ems f {:.4} GHz Q {:.2}",
        oe.0 / 1e9,
        oe.1,
        em.0 / 1e9,
        em.1
    );
    (oe, em)
}

#[test]
fn cylindrical_conducting_sheets_differ_from_openems_as_recorded() {
    let (none_oe, none_em) = both("cyl_sheet_none");
    // The empty cavities agree (no-axis cylindrical grids, §5.16.2).
    assert!((none_oe.0 / none_em.0 - 1.0).abs() < 5e-4);
    assert!(none_oe.1.abs() > 1e4 && none_em.1.abs() > 1e4);
    // Lossy tube: openEMS has about half the loss (Q 397 against 196).
    let (tube_oe, tube_em) = both("cyl_sheet_tube");
    assert!((tube_em.1 / 195.9 - 1.0).abs() < 0.01, "{tube_em:?}");
    let r = tube_oe.1 / tube_em.1;
    assert!((1.9..2.2).contains(&r), "openEMS/ems Q ratio {r}");
    // Resistive fin: openEMS detunes the mode by about −13 %.
    let (fin_oe, fin_em) = both("cyl_sheet_fin");
    assert!((fin_em.1 / 57.65 - 1.0).abs() < 0.02, "{fin_em:?}");
    assert!((fin_em.0 / none_em.0 - 1.0).abs() < 2e-3);
    let shift = fin_oe.0 / none_oe.0 - 1.0;
    assert!(
        (-0.16..-0.10).contains(&shift),
        "openEMS fin detuning {shift}"
    );
    // The same fin on the α = 0 seam: no effect in openEMS; ems as off it.
    let (seam_oe, seam_em) = both("cyl_sheet_seam");
    assert!((seam_oe.0 / none_oe.0 - 1.0).abs() < 1e-6);
    assert!(seam_oe.1.abs() > 1e4);
    assert!((seam_em.1 / fin_em.1 - 1.0).abs() < 2e-3);
}

/// openEMS ignores a plane wave on a cylindrical grid (no field at all,
/// no message; `cyl_planewave`); ems drops it with a warning.
#[test]
fn cylindrical_plane_wave_is_ignored_like_openems() {
    let text = std::fs::read_to_string(fixture("cyl_planewave").join("e_in")).unwrap();
    let rows: Vec<Vec<f64>> = text
        .lines()
        .filter(|l| !l.starts_with('%') && !l.trim().is_empty())
        .map(|l| l.split_whitespace().map(|x| x.parse().unwrap()).collect())
        .collect();
    assert!(rows.len() > 10);
    assert!(rows.iter().all(|r| r[1..].iter().all(|&x| x == 0.0)));
    let mut sim = Simulation::from_xml(fixture("cyl_planewave").join("model.xml")).unwrap();
    assert!(sim.plane_wave("pw").is_none());
    assert!(
        sim.warnings()
            .iter()
            .any(|w| w.contains("plane-wave excitation(s) ignored")),
        "{:?}",
        sim.warnings()
    );
    sim.step(50);
    assert_eq!(sim.engine().energy(), 0.0);
}
